def lessons_to_blocks(apps, schema_editor):
    """Each lesson's old single content becomes its first blocks."""
    Leccion = apps.get_model("aprendizaje", "Leccion")
    Bloque = apps.get_model("aprendizaje", "Bloque")
    for leccion in Leccion.objects.all():
        orden = 0

        def add(**fields):
            nonlocal orden
            orden += 1
            Bloque.objects.create(
                client_id=leccion.client_id, leccion=leccion, orden=orden, **fields
            )

        if leccion.tipo == "video" and leccion.url:
            add(tipo="video", url=leccion.url)
        elif leccion.tipo == "documento" and (leccion.archivo or leccion.url):
            add(tipo="documento", archivo=leccion.archivo.name or "", url=leccion.url)
        if leccion.contenido.strip():
            add(tipo="texto", texto=leccion.contenido)


